import json
from pathlib import Path
ROOT=Path(__file__).parent; E=ROOT/'evaluation'/'balanced-3class-150'
m=json.loads((E/'metrics.json').read_text(encoding='utf-8')); rows=json.loads((E/'scored_reviews.json').read_text(encoding='utf-8'))
payload=json.dumps({'metrics':m,'reviews':rows},ensure_ascii=False).replace('</','<\\/')
labels=['POSITIVE','NEUTRAL','NEGATIVE']
bar=''.join('<div class="metric"><div class="metric-name">%s</div><div class="metric-bars"><div class="mini p" style="width:%s%%"></div><div class="mini r" style="width:%s%%"></div><div class="mini f" style="width:%s%%"></div></div><div class="metric-values">%s / %s / %s</div></div>'%(x,m['per_class'][x]['precision']*100,m['per_class'][x]['recall']*100,m['per_class'][x]['f1']*100,round(m['per_class'][x]['precision']*100),round(m['per_class'][x]['recall']*100),round(m['per_class'][x]['f1']*100)) for x in labels)
cm=''.join('<tr><th>%s</th>%s</tr>'%(x,''.join('<td>%s</td>'%m['confusion_matrix'][x][y] for y in labels)) for x in labels)
rating_counts={str(i):sum(float(x['rating'])==i for x in rows) for i in range(1,6)}
class_counts={x:sum(r['reference']==x for r in rows) for x in labels}
pred_counts={x:sum(r['prediction']==x for r in rows) for x in labels}
correct_rates={x:sum(r['reference']==x and r['correct'] for r in rows)/class_counts[x] for x in labels}
star_chart=''.join('<div class="star-row"><div>%s★</div><div class="star-track"><div class="star-fill" style="width:%s%%;min-width:%s"></div></div><div class="metric-values">%s reviews</div></div>'%(i,rating_counts[str(i)]/max(rating_counts.values())*100,'3px' if rating_counts[str(i)] else '0',rating_counts[str(i)]) for i in range(1,6))
class_max=max(max(class_counts.values()),max(pred_counts.values()))
class_chart=''.join('<div class="class-row"><div>%s</div><div class="class-track"><div class="class-ref" style="width:%s%%"></div><div class="class-pred" style="width:%s%%"></div></div><div class="metric-values">%s / %s</div></div>'%(x,class_counts[x]/class_max*100,pred_counts[x]/class_max*100,class_counts[x],pred_counts[x]) for x in labels)
rate_chart=''.join('<div class="rate-row"><div>%s</div><div class="rate-track"><div class="rate-fill" style="width:%s%%;min-width:3px"></div></div><div class="metric-values">%.0f%% · %s/%s</div></div>'%(x,correct_rates[x]*100,correct_rates[x]*100,sum(r['reference']==x and r['correct'] for r in rows),class_counts[x]) for x in labels)
template='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Balanced three-class evaluation</title><style>
:root{--bg:#f4f6f2;--surface:#fff;--ink:#17221b;--muted:#657168;--line:#d7dfd7;--green:#277653;--orange:#b36a32;--red:#a8443d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1180px;margin:auto;padding:34px 24px 60px}.kicker{color:var(--green);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}h1{font-size:clamp(30px,4vw,50px);line-height:1.02;letter-spacing:-.055em;margin:8px 0 12px}.lede,.note{color:var(--muted)}.lede{max-width:760px;margin:0 0 24px}.rule{background:#fff9ed;border:1px solid #eedcc5;padding:12px 14px;color:#60431d}.cards{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);margin:24px 0;box-shadow:0 10px 28px #1b33220d}.card{background:var(--surface);padding:20px}.card:first-child{background:var(--green);color:#fff}.value{display:block;font-size:32px;font-weight:800;letter-spacing:-.05em}.label{font-size:12px;color:var(--muted)}.card:first-child .label{color:#d9ede1}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{background:var(--surface);border:1px solid var(--line);padding:20px;box-shadow:0 10px 28px #1b33220d;margin-top:16px}.metric{display:grid;grid-template-columns:95px 1fr 80px;align-items:center;gap:10px;margin:15px 0}.metric-bars{display:grid;gap:4px;background:#eef2ee;padding:4px}.mini{height:8px;min-width:2px}.mini.p{background:var(--green)}.mini.r{background:var(--orange)}.mini.f{background:var(--red)}.metric-values{font-size:11px;text-align:right;color:var(--muted);white-space:nowrap}.descriptive{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px}.star-row,.class-row,.rate-row{display:grid;grid-template-columns:88px 1fr 82px;align-items:center;gap:10px;margin:12px 0;font-size:12px}.star-track,.class-track,.rate-track{height:14px;background:#eef2ee;overflow:hidden;position:relative}.star-fill,.rate-fill{height:100%;background:var(--orange)}.class-track{height:24px}.class-ref,.class-pred{position:absolute;left:0;height:10px}.class-ref{top:2px;background:var(--green)}.class-pred{bottom:2px;background:var(--orange)}.rate-fill{background:var(--green)}.legend{font-size:11px;color:var(--muted)}.matrix{border-collapse:collapse;width:100%;font-size:12px}.matrix th,.matrix td{border:1px solid var(--line);padding:12px;text-align:center}.matrix th{color:var(--muted)}.matrix td{font-size:20px;font-weight:800}.matrix td.diag{background:#e4f2e9}.matrix td.off{background:#f9e8e5}.route{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}.route div{padding:15px;background:#eef2ee}.route strong{display:block;font-size:27px}.route small{color:var(--muted)}table.audit{width:100%;border-collapse:collapse} .audit th,.audit td{border-top:1px solid var(--line);padding:10px 6px;text-align:left;vertical-align:top}.audit th{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);white-space:nowrap}.audit small,.muted{color:var(--muted)}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.toolbar button,.toolbar input,.toolbar select{font:inherit;border:1px solid var(--line);background:#fff;color:var(--ink);padding:8px 10px;border-radius:5px}.toolbar button{cursor:pointer}.toolbar button.active{background:var(--ink);color:#fff}.toolbar input{min-width:210px;flex:1}.pill{display:inline-block;padding:3px 7px;border-radius:99px;font-size:10px;font-weight:800}.pos{color:#236746;background:#e4f2e9}.neu{color:#85501f;background:#faeddc}.neg{color:#963c36;background:#f9e8e5}.match{color:#236746}.miss{color:#963c36}.count{color:var(--muted);font-size:12px;margin-left:auto}footer{font-size:11px;color:var(--muted);margin-top:22px}@media(max-width:800px){main{padding:25px 15px}.cards,.grid{grid-template-columns:1fr}.card:first-child{grid-column:auto}.route{grid-template-columns:1fr}.metric{grid-template-columns:78px 1fr 70px}}@media(max-width:540px){.review-text{max-width:180px;overflow-wrap:anywhere}.audit{font-size:12px}}
</style></head><body><main><div class="kicker">Astra · Amazon Gift Cards · balanced benchmark</div><h1>Three classes, equal footing.</h1><p class="lede">A fixed-seed sample from the full 152,410-review file. Fifty reviews per class make the neutral class visible instead of letting the majority class dominate the score.</p><div class="rule"><strong>Reference labels:</strong> 4–5★ = POSITIVE · 3★ = NEUTRAL · 1–2★ = NEGATIVE &nbsp;|&nbsp; <strong>Seed:</strong> 6418</div><div class="cards"><div class="card"><span id="accuracy" class="value">__ACC__%</span><span class="label">accuracy · __CORRECT__/150</span></div><div class="card"><span id="macro" class="value">__F1__%</span><span class="label">macro F1</span></div><div class="card"><span id="balanced" class="value">__BAL__%</span><span class="label">balanced accuracy</span></div><div class="card"><span id="incorrect" class="value">__ERR__</span><span class="label">incorrect predictions</span></div></div><section class="panel"><h2>Descriptive view</h2><p class="note">Bars are normalized to the largest group. Counts are shown explicitly at right.</p><div class="descriptive"><div><h3>Sampled star ratings</h3>__STARS__</div><div><h3>Reference vs prediction</h3><p class="legend"><span class="mini p" style="display:inline-block;width:14px"></span> reference &nbsp; <span class="mini r" style="display:inline-block;width:14px"></span> Astra</p>__CLASSES__</div><div><h3>Answered correctly</h3>__RATES__</div></div></section><div class="grid"><section class="panel"><h2>Class performance</h2><p class="note">Each row shows precision / recall / F1. Every class has support of 50.</p>__BARS__<p class="legend"><span class="mini p" style="display:inline-block;width:14px"></span> precision &nbsp; <span class="mini r" style="display:inline-block;width:14px"></span> recall &nbsp; <span class="mini f" style="display:inline-block;width:14px"></span> F1</p></section><section class="panel"><h2>Confusion matrix</h2><p class="note">Rows = rating-derived reference; columns = Astra prediction.</p><table class="matrix"><thead><tr><th>Reference ↓ / Astra →</th><th>POS</th><th>NEU</th><th>NEG</th></tr></thead><tbody>__CM__</tbody></table></section></div><section class="panel"><h2>What happened to 3-star reviews?</h2><p class="note">The balanced run makes the middle class measurable. Astra preserves 17 of 50 as NEUTRAL, but collapses the other 33 into a polarity.</p><div class="route"><div><strong>17</strong><small>NEUTRAL · 34%</small></div><div><strong>25</strong><small>NEGATIVE · 50%</small></div><div><strong>8</strong><small>POSITIVE · 16%</small></div></div></section><section class="panel"><div style="display:flex;gap:12px;align-items:baseline;flex-wrap:wrap"><div><h2>Review-level audit</h2><p class="note" style="margin-bottom:0">Inspect every sampled review and filter by reference class, prediction, or result.</p></div><span class="count" id="count">150 reviews</span></div><div class="toolbar"><button class="active" data-filter="all">All</button><button data-filter="errors">Errors only</button><button data-filter="POSITIVE">Reference positive</button><button data-filter="NEUTRAL">Reference neutral</button><button data-filter="NEGATIVE">Reference negative</button><button data-filter="predicted-neutral">Predicted neutral</button><input id="search" placeholder="Search title or review text…"><select id="rating"><option value="all">All ratings</option><option value="1-2">1–2 stars</option><option value="3">3 stars</option><option value="4-5">4–5 stars</option></select></div><div style="overflow:auto"><table class="audit"><thead><tr><th>ID</th><th>Review</th><th>Rating</th><th>Reference</th><th>Astra</th><th>Result</th></tr></thead><tbody id="rows"></tbody></table></div></section><footer>Balanced sample: 150 rows from the full file, fixed seed 6418. LLM inputs excluded ratings and reference labels. Rating classes are a proxy target, not gold sentiment truth.</footer></main><script>const DATA=__PAYLOAD__;const reviews=DATA.reviews;let filter='all';const p=x=>(x*100).toFixed(2);document.querySelector('#accuracy').textContent=p(DATA.metrics.accuracy);document.querySelector('#balanced').textContent=p(DATA.metrics.balanced_accuracy);document.querySelector('#macro').textContent=p(DATA.metrics.macro_f1);document.querySelector('#rows');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelector('#search').oninput=render;document.querySelector('#rating').onchange=render;function render(){const q=document.querySelector('#search').value.toLowerCase(),rt=document.querySelector('#rating').value;const out=reviews.filter(r=>{const ref=r.reference,err=r.correct===false||r.correct==='False',rating=Number(r.rating);return(filter==='all'||(filter==='errors'&&err)||(filter===ref)||(filter==='predicted-neutral'&&r.prediction==='NEUTRAL'))&&(rt==='all'||(rt==='1-2'&&rating<=2)||(rt==='3'&&rating===3)||(rt==='4-5'&&rating>=4))&&(!q||(r.title+' '+r.text).toLowerCase().includes(q))});document.querySelector('#count').textContent=out.length+' review'+(out.length===1?'':'s');document.querySelector('#rows').innerHTML=out.map(r=>'<tr><td>#'+r.id+'</td><td><strong>'+esc(r.title)+'</strong><div class="review-text muted">'+esc(r.text)+'</div></td><td>'+r.rating+'★</td><td><span class="pill '+cls(r.reference)+'">'+r.reference+'</span></td><td><span class="pill '+cls(r.prediction)+'">'+r.prediction+'</span></td><td class="'+(r.correct===true||r.correct==='True'?'match':'miss')+'">'+(r.correct===true||r.correct==='True'?'✓ correct':'✕ mismatch')+'</td></tr>').join('')||'<tr><td colspan="6">No reviews match these filters.</td></tr>'}function cls(x){return x==='POSITIVE'?'pos':x==='NEUTRAL'?'neu':'neg'}function esc(s){return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}render();</script></body></html>'''
html=template.replace('__PAYLOAD__',payload).replace('__ACC__',str(m['accuracy']*100)).replace('__CORRECT__',str(m['correct'])).replace('__F1__',str(m['macro_f1']*100)).replace('__BAL__',str(m['balanced_accuracy']*100)).replace('__ERR__',str(m['incorrect'])).replace('__BARS__',bar).replace('__CM__',cm).replace('__STARS__',star_chart).replace('__CLASSES__',class_chart).replace('__RATES__',rate_chart)
out=E/'dashboard.html';out.write_text(html,encoding='utf-8');print(f'Wrote {out} ({out.stat().st_size} bytes)')
